import type { Account, Mailer } from "./types";

export async function notifyAccounts(accounts: Account[], mailer: Mailer): Promise<void> {
  for (const account of accounts) {
    if (!account.allowEmail) continue;
    await mailer.send(account.email, "Your monthly account summary");
  }
}

