import type { Account, Mailer } from "./types";
import { subjectFor } from "./subject";

export async function notifyAccounts(accounts: Account[], mailer: Mailer): Promise<void> {
  accounts.forEach(async (account) => {
    await mailer.send(account.email, subjectFor(account));
  });
}

import type { Account } from "./types";

export function subjectFor(account: Account): string {
  return `Monthly summary for ${account.id}`;
}

